// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address callerSeed) public {
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed)))));
        vm.assume(caller != address(0));

        BankHelper helper = new BankHelper();

        vm.deal(address(helper), 1 ether);

        bool ok;
        try helper.callAirDrop(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "first airdrop must succeed");
        assertTrue(c.tokenBalance(address(helper)) == 20, "after first airdrop balance should be 20");

        bool ok2;
        try helper.callAirDrop(address(c)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2, "reference: second airdrop from same caller must NOT succeed");
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address caddr) external {
        ModifierEntrancy(caddr).airDrop();
    }
}
